import{_ as o,o as d,c as r,ag as e}from"./chunks/framework.D5hoimZQ.js";const l=JSON.parse('{"title":"DSH 插件生态：从梗插件到\\"Token 自由\\"额度聚合","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/dsh-plugin-ecosystem.md","filePath":"topics/ai-system-architecture/dsh-plugin-ecosystem.md"}'),s={name:"topics/ai-system-architecture/dsh-plugin-ecosystem.md"};function n(a,t,g,i,c,u){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="dsh-插件生态-从梗插件到-token-自由-额度聚合" tabindex="-1">DSH 插件生态：从梗插件到&quot;Token 自由&quot;额度聚合 <a class="header-anchor" href="#dsh-插件生态-从梗插件到-token-自由-额度聚合" aria-label="Permalink to &quot;DSH 插件生态：从梗插件到&quot;Token 自由&quot;额度聚合&quot;">​</a></h1><blockquote><p><strong>来源①</strong>：2026-10-20 飞书分享（&quot;在 DSH 安装&#39;滑动变祖器&#39;插件，拖动滑块调节推理强度&quot;） <strong>来源②</strong>：2026-10-20 飞书分享（&quot;开源插件 <code>dsh-workbuddy-connect</code> 接入 WorkBuddy 多模型，无需 API Key 免费调用&quot;） <strong>核实</strong>：GitHub API 实测（仓库元数据 + README 原文，2026-10-20） 关键词：DeepSeek Harness、DSH、插件生态、一切皆插件、Cordis、滑动变祖器、梁系强度校准器、liang-intensity-calibrator、Liang-Saint-Slider、dsh-liang-skin、dsh-liang-watch、awesome-dsh-plugin、dsh-market、趣味插件、梗、二创、开发者预览、兼容性破坏、肖像权、素材许可、coding agent 了解项目、插件市场</p></blockquote><hr><h2 id="一、视频说法-vs-实测-又一处-转述-仓库事实" tabindex="-1">一、视频说法 vs 实测（又一处&quot;转述 ≠ 仓库事实&quot;） <a class="header-anchor" href="#一、视频说法-vs-实测-又一处-转述-仓库事实" aria-label="Permalink to &quot;一、视频说法 vs 实测（又一处&quot;转述 ≠ 仓库事实&quot;）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>视频说法</th><th>实测</th><th>判定</th></tr></thead><tbody><tr><td>在 DSH 中安装&quot;滑动变祖器&quot;<strong>插件</strong></td><td>原版&quot;滑动变祖器&quot;是一个<strong>网页小玩具</strong>（GitHub Pages 部署，<code>Lichtspektrum/liang-intensity-calibrator</code>），<strong>本身不是 DSH 插件</strong></td><td>⚠️ 张冠李戴：把&quot;网页玩具&quot;和&quot;DSH 插件二创&quot;混成一件事</td></tr><tr><td>拖动滑块<strong>调节模型推理强度</strong></td><td>原版网页<strong>没有</strong>这个功能，只有滑杆 + 社区投票；把滑杆接成 DSH <strong>模型/思考强度选择器</strong>的是二创 <code>BruzWJ/Liang-Saint-Slider</code></td><td>⚠️ 功能归属错位</td></tr><tr><td>头像在&quot;小难梁 / 梁子 / 梁圣 / 梁祖&quot;间切换</td><td>README 原文：<strong>六个状态 —— 小难梁、牢梁、梁子、梁圣、梁神、梁祖</strong>；滑杆 <strong>−15 ~ +15（31 级）</strong>，逐帧视频让中间状态平滑过渡</td><td>✅ 基本属实，<strong>视频漏了&quot;牢梁&quot;&quot;梁神&quot;</strong></td></tr><tr><td>DSH 是高度可定制的开源 AI 运行环境</td><td>✅ <code>deepseek-ai/deepseek-harness</code> <strong>★254,706</strong>（fork 30,785），<strong>&quot;Everything is a Plugin&quot;</strong>，MIT，Cordis 微内核</td><td>✅ 准确</td></tr><tr><td>AI 会指导安装方法</td><td>README 原话：<strong>&quot;如需本地部署或安装，请使用 coding agent 来了解项目架构等细节&quot;</strong></td><td>✅ 属实 —— 且这已是<strong>一种 README 新惯例</strong>（与 cleanyourtv 的 PROMPT.md 同款手法）</td></tr></tbody></table><hr><h2 id="二、被点名的仓库实况" tabindex="-1">二、被点名的仓库实况 <a class="header-anchor" href="#二、被点名的仓库实况" aria-label="Permalink to &quot;二、被点名的仓库实况&quot;">​</a></h2><p><code>Lichtspektrum/liang-intensity-calibrator</code></p><table tabindex="0"><thead><tr><th>项</th><th>实测</th></tr></thead><tbody><tr><td>Stars / Forks / Watch</td><td><strong>328</strong> / 36 / <strong>0</strong></td></tr><tr><td>创建 / 最后推送</td><td><strong>2026-08-10</strong> / <strong>2026-08-16</strong>（<strong>已 2 个月无更新</strong>）</td></tr><tr><td>许可 / 语言</td><td><strong>MIT</strong> / TypeScript</td></tr><tr><td>描述原文</td><td>&quot;滑动变祖器：31 级梁系强度校准器&quot;</td></tr><tr><td>架构</td><td>前端与视频帧在 <strong>GitHub Pages</strong>；<strong>Cloudflare Worker</strong> 提供 <code>/api/score</code>、<code>/api/vote</code>、<code>/api/timeline</code>；投票与每日快照存 <strong>D1</strong> —— <strong>有真实后端，不是纯静态页</strong></td></tr><tr><td>机制</td><td>每浏览器一张票、<strong>每 3 小时</strong>可改；灰点 = 社区平均分；每天记一次社区均值快照做<strong>时间线</strong>；支持鼠标/触摸/键盘</td></tr></tbody></table><blockquote><p>⚠️ <strong>许可边界（重要）</strong>：<strong>源代码 MIT，但人像素材与视频帧不随 MIT 共享</strong>。README 原话：&quot;复用或二次发布前，请确认你拥有相关肖像与素材的使用权。&quot; → <strong>代码开源 ≠ 素材可用</strong>。涉及真实人物肖像的&quot;梗类项目&quot;，二次分发风险由使用者承担。</p></blockquote><hr><h2 id="三、一个梗长成的-插件链-readme-的-awesome-sliders-二创区" tabindex="-1">三、一个梗长成的&quot;插件链&quot;（README 的 Awesome Sliders 二创区） <a class="header-anchor" href="#三、一个梗长成的-插件链-readme-的-awesome-sliders-二创区" aria-label="Permalink to &quot;三、一个梗长成的&quot;插件链&quot;（README 的 Awesome Sliders 二创区）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>二创项目</th><th>作者</th><th>做了什么</th><th>与 DSH 的关系</th></tr></thead><tbody><tr><td><strong><code>BruzWJ/Liang-Saint-Slider</code></strong></td><td>BruzWJ</td><td>把滑杆做成 <strong>DSH 的模型与思考强度选择器</strong></td><td>✅ <strong>真·DSH 功能插件</strong> —— 视频&quot;调节推理强度&quot;的真实出处</td></tr><tr><td><strong><code>kingOfSoySauce/dsh-liang-skin</code></strong></td><td>kingOfSoySauce</td><td><strong>DSH 滑动变阻器皮肤</strong></td><td>✅ DSH 界面插件</td></tr><tr><td><strong><code>huangmouren2023/deepseek-harness-toolkit</code> → <code>dsh-liang-watch</code></strong></td><td>huangmouren2023</td><td><strong>&quot;梁强度雷达&quot;</strong>：把社区投票与每日时间线变成<strong>模型工具 + 侧边栏面板</strong>，可在对话里直接查分、投票、看趋势</td><td>✅ DSH 工具 + UI 插件</td></tr><tr><td><code>Lichtspektrum/liang-intensity-calibrator-ascii</code></td><td>原作者</td><td>原项目 31 张关键帧逐帧转成<strong>纯 ASCII 动画</strong></td><td>与 DSH 无关，纯二创</td></tr></tbody></table><p><strong>传播模式</strong>：趣味网页 → 社区把它<strong>接进宿主工具</strong>（模型选择器 / 皮肤 / 侧边栏面板）→ 梗获得&quot;生产力外壳&quot;。 <strong>关键</strong>：<strong>&quot;Everything is a Plugin&quot; 让这种接法成本极低</strong>——不用改宿主源码，所以一个 328 星的小玩具能立刻长出三种 DSH 集成。</p><hr><h2 id="四、dsh-插件生态全景-2026-10-20-github-实测" tabindex="-1">四、DSH 插件生态全景（2026-10-20 GitHub 实测） <a class="header-anchor" href="#四、dsh-插件生态全景-2026-10-20-github-实测" aria-label="Permalink to &quot;四、DSH 插件生态全景（2026-10-20 GitHub 实测）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>★</th><th>创建</th><th>说明</th></tr></thead><tbody><tr><td><code>deepseek-ai/deepseek-harness</code></td><td><strong>254,706</strong></td><td>2026-08-13</td><td><strong>官方本体</strong>。&quot;Everything is a Plugin&quot;，MIT，Cordis 微内核；最近推送 2026-10-17</td></tr><tr><td><code>anywhere-labs/dsh-desktop</code></td><td>31,829</td><td>2026-08-13</td><td>第三方桌面端（&quot;桌面本身也是插件&quot;）</td></tr><tr><td><code>awesome-dsh-plugin/awesome-dsh-plugin</code></td><td>19,582</td><td>2026-08-13</td><td>插件精选列表</td></tr><tr><td><code>zhu1090093659/dsh-web</code></td><td>9,050</td><td>2026-08-12</td><td>Web 插件聚合生态 / &quot;创意工坊&quot;分发</td></tr><tr><td><code>dsh-market/dsh-market</code></td><td>7,541</td><td>2026-08-14</td><td><strong>DSH 内的插件市场</strong>：浏览 / 搜索 / 一键安装</td></tr><tr><td><code>MeteorNOX/DeepSeek-Balance-Whale-Widget</code></td><td>5,448</td><td>2026-08-18</td><td>同类趣味插件：右下角小鲸鱼娘盯 DeepSeek 账户余额（可拖拽吸附、数字滚动动画）</td></tr><tr><td><code>Lichtspektrum/liang-intensity-calibrator</code></td><td>328</td><td>2026-08-10</td><td>本次&quot;滑动变祖器&quot;原版</td></tr></tbody></table><ul><li><strong>运行</strong>：<code>npx @deepseek-ai/dsh web</code> → 默认 <code>http://127.0.0.1:3080</code></li><li><strong>架构论文</strong>：Cordis 的设计见 arXiv <strong>2608.25512</strong>《A Programming Paradigm for Spatiotemporal Composability》——&quot;时空可组合性&quot;</li><li>⚠️ <strong>官方定位</strong>：<strong>developer preview</strong>，&quot;<strong>THERE WILL BE COMPATIBILITY-BREAKING CHANGES</strong>&quot;；运行前须读仓库 <strong>SAFETY.md</strong></li></ul><hr><h2 id="五、与库内已有-dsh-文档的分工" tabindex="-1">五、与库内已有 DSH 文档的分工 <a class="header-anchor" href="#五、与库内已有-dsh-文档的分工" aria-label="Permalink to &quot;五、与库内已有 DSH 文档的分工&quot;">​</a></h2><ul><li><code>deepseek-harness-agent-runtime.md</code>（2026-08-21 落盘）讲<strong>运行时本体</strong>：一切皆插件 / 轨迹持久化（黑匣子）/ 沙箱三档 / 四种运行模式。★当时 188,058。</li><li><strong>本文补生态层</strong>：插件市场、二创链、&quot;梗 → 插件&quot;的传播样本。</li><li><strong>星数变化</strong>：★188,058（08-21）→ <strong>★254,706（10-20）</strong>，两个月 <strong>+66,648</strong>。</li></ul><hr><h2 id="六、可复用教训-元" tabindex="-1">六、可复用教训（元） <a class="header-anchor" href="#六、可复用教训-元" aria-label="Permalink to &quot;六、可复用教训（元）&quot;">​</a></h2><ol><li><strong>先分清&quot;宿主&quot;和&quot;被转述的品牌词&quot;</strong>。&quot;在 X 里装了个插件&quot;——要问：X 是宿主工具，还是只是视频借用的名头？本次真身是<strong>网页玩具</strong>，DSH 集成全在二创里。</li><li><strong>&quot;用 coding agent 来了解项目&quot;正在变成 README 惯例</strong>。这既方便（AI 能读架构细节），也是<strong>信任转移</strong>：内容不再由人直接审阅，读者被引导把理解权交给模型。<strong>本项目与 cleanyourtv 同款</strong>——两次出现，值得记为一个模式。</li><li><strong>梗类项目的许可陷阱</strong>：<strong>代码 MIT ≠ 素材可用</strong>。人像/视频帧通常被单独排除。</li><li><strong>星数 + watch + 最后推送是最便宜的真伪筛子</strong>：★328 / watch 0 / 2 个月未更新 = <strong>个人玩具级</strong>，不是基础设施；与官方 ★254,706 差 <strong>3 个数量级</strong>。上次（tv-vibehack ★26 vs cleanyourtv ★4,310）是同一把尺子的另一次使用。</li></ol><hr><h2 id="七、-token-自由-dsh-workbuddy-connect-实测-2026-10-20" tabindex="-1">七、&quot;Token 自由&quot;：<code>dsh-workbuddy-connect</code> 实测（2026-10-20） <a class="header-anchor" href="#七、-token-自由-dsh-workbuddy-connect-实测-2026-10-20" aria-label="Permalink to &quot;七、&quot;Token 自由&quot;：`dsh-workbuddy-connect` 实测（2026-10-20）&quot;">​</a></h2><blockquote><p>视频说法：开源插件 <code>dsh-workbuddy-connect</code> 让 DSH 用户<strong>无需 API Key、无需独立网关</strong>，只要本地登录 WorkBuddy 账号，就能直接使用 DeepSeek Flash、Step-5 等模型；插件自动读取本地客户端登录态与模型目录，支持国内版/国际版双账号。</p></blockquote><h3 id="_7-1-核实结果" tabindex="-1">7.1 核实结果 <a class="header-anchor" href="#_7-1-核实结果" aria-label="Permalink to &quot;7.1 核实结果&quot;">​</a></h3><table tabindex="0"><thead><tr><th>视频说法</th><th>实测</th><th>判定</th></tr></thead><tbody><tr><td>开源插件 <code>dsh-workbuddy-connect</code> 存在</td><td><strong>真实</strong> —— <code>corrinehu/dsh-workbuddy-connect</code> ★<strong>1,463</strong> / fork 139 / watch 5 / issues 20 / <strong>MIT</strong> / TypeScript / 创建 <strong>2026-08-17</strong> / 最后推送 <strong>2026-10-20</strong> / 4.2 MB</td><td>✅</td></tr><tr><td>无需 API Key、无需独立网关</td><td>✅ 准确 —— README：「插件<strong>直接复用 App 的登录状态</strong>，账号切换自动跟随，两版互不影响」</td><td>✅</td></tr><tr><td>自动读取本地登录态与模型目录</td><td>✅ 准确 —— 复用 App 登录态 + 模型目录；另有令牌有效期显示与 <code>status</code> / <code>doctor</code> / <code>logout</code> 子命令</td><td>✅</td></tr><tr><td>支持国内版与国际版双账号</td><td>✅ 准确 —— 国内版显示「WorkBuddy」分组，国际版「WorkBuddy AI」分组，<strong>模型、账号、积分互不混用</strong>；各自跟随对应 App 登录态，退出一版则该分组消失</td><td>✅</td></tr><tr><td>&quot;DeepSeek Flash、Step-5 等模型&quot;</td><td>⚠️ <strong>部分对不上</strong> —— README 列的是 <strong>GLM-5.3 / GLM-5.2 / DeepSeek-V4-Pro / DeepSeek-V4-Flash / Kimi-K3 / MiniMax-M3 / Hy3</strong>；<strong>未见 &quot;Step-5&quot;</strong>（阶跃星辰）</td><td>⚠️</td></tr></tbody></table><h3 id="_7-2-⚠️-插件名不唯一-装错就出事" tabindex="-1">7.2 ⚠️ 插件名不唯一（装错就出事） <a class="header-anchor" href="#_7-2-⚠️-插件名不唯一-装错就出事" aria-label="Permalink to &quot;7.2 ⚠️ 插件名不唯一（装错就出事）&quot;">​</a></h3><p><strong>同一个名字 <code>dsh-workbuddy-connect</code> 至少两个仓库，行为完全不同</strong>：</p><table tabindex="0"><thead><tr><th>仓库</th><th>★</th><th>登录方式</th></tr></thead><tbody><tr><td><code>corrinehu/dsh-workbuddy-connect</code></td><td><strong>1,463</strong></td><td><strong>复用已登录的桌面 App</strong>（← 视频描述贴合这个）</td></tr><tr><td><code>masknull/dsh-workbuddy-connect</code></td><td>48</td><td><strong>插件自己登录</strong> —— &quot;不需要安装 WorkBuddy 桌面 App&quot;，卡片点登录或 <code>dsh-workbuddy-connect login</code>；含<strong>每日自动签到</strong></td></tr><tr><td><code>dingminhua/dsh-connect-workbuddy</code></td><td>212</td><td>名字<strong>倒装</strong>；read-only 额度总览 + 模型管理</td></tr><tr><td><code>iceloon/dsh-workbuddyai-connect</code></td><td>3</td><td>只接国际版，默认只显示免费模型</td></tr></tbody></table><p>→ <strong>视频没给作者名 → 无法唯一确定装的是哪个</strong>。<strong>认 <code>owner/repo</code>，不认插件名。</strong></p><h3 id="_7-3-版本兼容是硬门槛-视频完全没提" tabindex="-1">7.3 版本兼容是硬门槛（视频完全没提） <a class="header-anchor" href="#_7-3-版本兼容是硬门槛-视频完全没提" aria-label="Permalink to &quot;7.3 版本兼容是硬门槛（视频完全没提）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>DSH 内核</th><th>配套插件版</th></tr></thead><tbody><tr><td>0.2.1-rc.2</td><td><strong>0.7.9</strong>（npm latest）</td></tr><tr><td>0.2.1-rc.1</td><td>0.7.7</td></tr><tr><td>0.2.0-rc.2</td><td>0.7.6</td></tr><tr><td>0.2.0-rc.1</td><td>0.7.0</td></tr><tr><td>0.1.5 – 0.1.7</td><td>0.6.5</td></tr></tbody></table><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Web（按实际内核固定版本）</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dsh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> plugin</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dsh-workbuddy-connect@0.7.9</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dsh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> web</span></span></code></pre></div><ul><li><strong>TUI</strong>：终端壳 <code>@deepseek-harness-tui/dsh-tui</code> 需 <strong>≥ 0.10.0-beta.5</strong>，更早装会<strong>启动失败</strong>（<code>events is not iterable</code>）；推理档位手动检测<strong>仅 Web / Desktop 提供，TUI 没有</strong></li><li><strong>Desktop</strong>：官方 Electron 版 <code>desktop</code> profile <strong>由 App 管理，会直接拒绝独立 CLI 的 <code>--profile desktop</code></strong>；各发行版规则不同，README 自己写&quot;<strong>不保证可行</strong>&quot;</li><li><strong>验证标准</strong>：重启界面后模型选择器出现「WorkBuddy / WorkBuddy AI」分组，并能完成一次真实对话</li></ul><h3 id="_7-4-📌-惯例第-3-次出现-readme-首推-把安装交给-agent" tabindex="-1">7.4 📌 惯例第 3 次出现：README 首推&quot;把安装交给 Agent&quot; <a class="header-anchor" href="#_7-4-📌-惯例第-3-次出现-readme-首推-把安装交给-agent" aria-label="Permalink to &quot;7.4 📌 惯例第 3 次出现：README 首推&quot;把安装交给 Agent&quot;&quot;">​</a></h3><p>README「安装」章的第一推荐不是命令，而是<strong>把一段提示词原样发给本机已有的 Agent</strong>（DSH Agent / Codex / Claude Code / Cursor 都行）：</p><blockquote><p>&quot;请帮我安装并验证 DSH 插件 <code>dsh-workbuddy-connect</code>…先阅读项目 README，确认我实际使用的界面与 DSH 内核版本…<strong>任何本地文件或配置改动，先征得我同意并做好备份</strong>…若 Desktop 安装仍因 generation 校验失败…请<strong>如实报告</strong>…不要修改依赖包或绕过校验。&quot;</p></blockquote><p>→ 与 <code>cleanyourtv</code> 的 <code>PROMPT.md</code>、滑杆项目 README 同款手法，<strong>这是第 3 例</strong>（本文件第二节已记为模式）。 → 但<strong>这次的提示词明显更克制</strong>：明确要求<strong>先备份、先要许可、不绕过校验、失败如实报告</strong> —— 是&quot;把操作外包&quot;与&quot;保留人审&quot;之间较好的一个折中。</p><h3 id="_7-5-⚠️-风险面-这条最该说的" tabindex="-1">7.5 ⚠️ 风险面（这条最该说的） <a class="header-anchor" href="#_7-5-⚠️-风险面-这条最该说的" aria-label="Permalink to &quot;7.5 ⚠️ 风险面（这条最该说的）&quot;">​</a></h3><ol><li><strong>它必须持有你的令牌才能工作</strong> —— README 自己列出「<strong>令牌有效期</strong>」显示与 <code>logout</code>（清理凭据）子命令，凭据落在 <code>workbuddy.json</code>。<strong>读你登录态的插件天然在信任边界之内</strong>；这不是 bug，是设计。装之前该问：owner 是谁？凭据存在哪个文件？怎么撤销？</li><li><strong>&quot;免费&quot;的真相是别人的订阅额度</strong> —— 积分<strong>不自动轮询</strong>，原因写得很直白：「每次读取都是<strong>真实计费查询</strong>」；推理档位检测「<strong>会消耗积分</strong>」。不是无限免费，是<strong>把 WorkBuddy 的付费额度转接到 DSH</strong>。</li><li><strong>促销窗口随时关</strong> —— <code>限时免费</code>、<code>夜间折扣</code> 徽章由<strong>服务端</strong>下发，「过期后徽章自动撤销」；README 甚至记了一个细节：<strong>服务端把折后价直接写进倍率字段，原价无法还原</strong> → <strong>定价权 100% 在厂商手里</strong>。</li><li><strong>企业账号要特别小心</strong> —— 国内版企业账号（<code>enterpriseId</code> 非空）走<strong>企业计费接口</strong>读周期额度。用<strong>公司账号</strong>接出来跑私活 = <strong>用公司额度做私事</strong>；对有内部 AI 平台的单位，合规上尤其敏感。</li><li><strong>违反 ToS 的可能性高</strong> —— 把订阅客户端额度转接到第三方客户端，几乎必然与厂商协议冲突。生态里 <code>workbuddy2api-panel</code>（★4,110）公开写&quot;<strong>自动完成任务中心全部任务</strong>&quot;（= 自动刷积分）、<code>masknull</code> 版带「<strong>每日自动签到</strong>」→ 这类行为被风控识别即封号。</li><li><strong>同名仓库 = 供应链风险</strong> —— ★3 / ★48 / ★1,463 三个同名或近名仓库行为不同，随手搜一个装可能拿到完全不同的代码。</li></ol><h3 id="_7-6-📊-灰色生态全景-github-api-实测-2026-10-20" tabindex="-1">7.6 📊 灰色生态全景（GitHub API 实测，2026-10-20） <a class="header-anchor" href="#_7-6-📊-灰色生态全景-github-api-实测-2026-10-20" aria-label="Permalink to &quot;7.6 📊 灰色生态全景（GitHub API 实测，2026-10-20）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>仓库</th><th>★</th><th>做什么</th></tr></thead><tbody><tr><td><code>KimYx0207/AI-Coding-Guide-Zh</code></td><td>6,298</td><td>Claude Code / OpenClaw / Codex / WorkBuddy 中文教程 50 篇</td></tr><tr><td><code>linguo2625469/workbuddy2api-panel</code></td><td><strong>4,110</strong></td><td>把<strong>腾讯 WorkBuddy 账号</strong>变成 OpenAI 兼容 API 网关 + <strong>自动完成任务中心全部任务</strong> + 账号池可视化面板</td></tr><tr><td><code>AlephAITech/WorkBuddyGuide</code></td><td>3,532</td><td>WorkBuddy 实操指南</td></tr><tr><td><code>babygoton/WorkDaddy</code></td><td>2,120</td><td>桌面增强：<strong>签到猫猫</strong>、多账号独立备份、跨账号会话迁移、免打扰长任务</td></tr><tr><td><code>ardeyouxipianyi/workbuddy2api-hub</code></td><td>2,080</td><td>国际/国内<strong>多账号反代网关</strong>，支持 Codex / Claude Code / <strong>DSH</strong> / 标准 OpenAI 客户端</td></tr><tr><td><strong><code>corrinehu/dsh-workbuddy-connect</code></strong></td><td><strong>1,463</strong></td><td><strong>本次视频说的这个</strong> —— 复用 App 登录态接进 DSH</td></tr><tr><td><code>z91772524-ai/pojia-next</code></td><td>544</td><td>一个脚本改 DSH / WorkBuddy / ZCode / Codex / Cursor / Claude <strong>六端提示词与人格</strong></td></tr><tr><td><code>dingminhua/dsh-connect-workbuddy</code></td><td>212</td><td>同功能、名字倒装</td></tr><tr><td><code>XDTrees/dsh-xdpool</code></td><td>185</td><td>&quot;把你能<strong>白嫖</strong>的模型额度接进 DSH 同一个池：WorkBuddy 多账号自动容错、<strong>十三家扫码登录</strong>、<strong>76 家免费额度聚合</strong>、积分自动化&quot;</td></tr><tr><td><code>masknull/dsh-workbuddy-connect</code></td><td>48</td><td>同名，自带登录 + <strong>每日自动签到</strong></td></tr></tbody></table><p><strong>关键词云</strong>：白嫖、签到、账号池、多账号轮询、反代网关、额度聚合、自动容错、积分自动化。 → 这是一个<strong>围绕&quot;把付费额度接出来免费使用&quot;的完整灰色生态</strong>；DSH 只是它最新的宿主之一。</p><h3 id="_7-7-🔑-workbuddy-是什么-顺带核实" tabindex="-1">7.7 🔑 WorkBuddy 是什么（顺带核实） <a class="header-anchor" href="#_7-7-🔑-workbuddy-是什么-顺带核实" aria-label="Permalink to &quot;7.7 🔑 WorkBuddy 是什么（顺带核实）&quot;">​</a></h3><ul><li><strong>腾讯的产品</strong> —— 搜狗实测到报道《<strong>WorkBuddy 开放平台上线：腾讯 AI 生态押注的不是模型，是连接</strong>》（翼言商业观察，2026-09-06）；<code>workbuddy2api-panel</code> 描述直接写&quot;把<strong>腾讯</strong>WorkBuddy账号…&quot;；相关项目 <code>workbuddy-manager</code> 描述写&quot;<strong>腾讯 CodeBuddy 账号池管理</strong>&quot;</li><li>与腾讯 <strong>CodeBuddy</strong> 同源（多个仓库 topics 同时挂 <code>codebuddy</code> + <code>workbuddy</code>）</li><li>官网 <strong>workbuddy.ai</strong>（国际版）；国内版与国际版<strong>账号、积分、模型优惠不通用</strong>（插件 README 与中文教程都强调）</li></ul><hr><p>关键词：DeepSeek Harness、DSH、插件生态、一切皆插件、Cordis、时空可组合性、滑动变祖器、梁系强度校准器、liang-intensity-calibrator、Liang-Saint-Slider、dsh-liang-skin、dsh-liang-watch、dsh-desktop、awesome-dsh-plugin、dsh-market、趣味插件、梗、二创、开发者预览、兼容性破坏、肖像权、素材许可、coding agent 了解项目、插件市场、真伪筛子、dsh-workbuddy-connect、WorkBuddy、WorkBuddy AI、腾讯、CodeBuddy、Token 自由、免费额度、白嫖、账号池、多账号轮询、反代网关、workbuddy2api、额度聚合、自动签到、积分任务、登录态复用、令牌、凭据信任边界、订阅额度转接、服务条款、封号风险、供应链风险、同名仓库、XDTrees、xdpool、WorkDaddy、模型分组、推理档位、版本兼容、内核版本、GLM-5.3、DeepSeek-V4、Kimi-K3、MiniMax-M3、Hy3、Step-5</p><p>关联：<code>topics/ai-system-architecture/deepseek-harness-agent-runtime.md</code>（运行时本体）、<code>topics/ai-system-architecture/index.md</code>、<code>topics/ai-tools/android-tv-debloat-cleanyourtv.md</code>（同款&quot;用 coding agent 了解项目&quot;惯例 + &quot;便利换暴露&quot;）、<code>topics/ai-system-architecture/echo-gap-memory-reward-inflation.md</code>（同一元模式）、<code>topics/ai-system-architecture/llm-cache-pricing.md</code>（定价不透明同源）、<code>topics/cybersecurity/index.md</code>（凭据信任边界 / 账号滥用模式）</p>',51)])])}const p=o(s,[["render",n]]);export{l as __pageData,p as default};
